class Solution { private fun next(value:CharArray){var i=value.size-2;while(i>=0&&value[i]>=value[i+1])i--;var j=value.lastIndex;while(value[j]<=value[i])j--;var temporary=value[i];value[i]=value[j];value[j]=temporary;var left=i+1;var right=value.lastIndex;while(left<right){temporary=value[left];value[left++]=value[right];value[right--]=temporary}};fun getMinSwaps(num:String,kValue:Int):Int{val target=num.toCharArray();repeat(kValue){next(target)};val current=num.toCharArray();var swaps=0;for(i in current.indices){var j=i;while(current[j]!=target[i])j++;swaps+=j-i;while(j>i){val temporary=current[j];current[j]=current[j-1];current[j-1]=temporary;j--}};return swaps} }
